<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Box, ChatDotRound, Connection, Cpu, Document, House, List, MapLocation, Plus, Search, Setting, Tickets } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import KnowledgeList from './components/KnowledgeList.vue'
import ProductList from './components/ProductList.vue'
import KnowledgeDetail from './components/KnowledgeDetail.vue'
import ProductDetail from './components/ProductDetail.vue'
import RelationDrawer from './components/RelationDrawer.vue'
import ImageUpload from './components/ImageUpload.vue'
import SystemAdmin from './components/SystemAdmin.vue'
import Phase2Workspace from './components/Phase2Workspace.vue'

type User={username:string;displayName:string;role:string;permissions:string[]}
type CenterKey='products'|'software'|'algorithms'|'model-capabilities'|'scenes'|'solutions'
const route=useRoute(),router=useRouter()
const token=ref(localStorage.hzToken||''),user=ref<User|null>(null),loginForm=reactive({username:'',password:''}),loginError=ref('')
const loading=ref(false),loadError=ref(''),rows=ref<any[]>([]),active=ref<any>(null),metrics=ref<Record<string,number>>({}),categories=ref<any[]>([])
const productDialog=ref(false),catalogDialog=ref(false),relationDrawer=ref(false),bomDialog=ref(false),saving=ref(false),editingId=ref<number|null>(null),dialogCenter=ref<CenterKey>('software'),sceneOptions=ref<any[]>([]),bomRows=ref<any[]>([])

const centers=[{key:'products',label:'产品中心',icon:Box,description:'统一沉淀产品、主型号、技术参数与关联知识。',placeholder:'搜索产品名称、主型号或分类'},{key:'software',label:'软件中心',icon:Cpu,description:'统一管理软件平台、版本与适配关系。',placeholder:'搜索软件名称、版本或简介'},{key:'algorithms',label:'算法中心',icon:Connection,description:'统一管理算法版本、类型与业务用途。',placeholder:'搜索算法名称、版本或分类'},{key:'model-capabilities',label:'模型能力中心',icon:Connection,description:'统一管理可复用模型能力、指标与部署要求。',placeholder:'搜索模型能力名称或分类'},{key:'scenes',label:'场景中心',icon:MapLocation,description:'从业务问题出发组织产品、能力与解决方案。',placeholder:'搜索场景名称或业务简介'},{key:'solutions',label:'方案中心',icon:Tickets,description:'沉淀标准方案、场景关系与标准BOM。',placeholder:'搜索方案名称、场景或等级'}] as const
const currentCenter=computed<CenterKey>(()=>String(route.name||'products').replace(/-detail$/,'') as CenterKey)
const currentMeta=computed(()=>centers.find(item=>item.key===currentCenter.value)||centers[0])
const isDetail=computed(()=>String(route.name||'').endsWith('-detail'))
const can=(permission:string)=>user.value?.permissions.includes(permission)||false

const productForm=reactive({name:'',product_type:'HARDWARE',model_code:'',category_id:null as number|null,summary:'',status:'ON_SALE',main_image:''})
const catalogForm=reactive({name:'',summary:'',description:'',code:'',version:'v1.0',category:'通用',logo:'',modules:'',versions:'',screenshots:'',cover_image:'',pain_points:'',goals:'',business_process:'',conditions:'',tags:'',core_capability_summary:'',function_type:'识别',model_type:'DETECTION',task_type:'',principle:'',input_summary:'',output_summary:'',parameters:'',metrics:'',input_requirements:'',output_definitions:'',deployment_requirements:'',use_conditions:'',boundaries:'',software_type:'PLATFORM',vendor:'海智科技',deployment_mode:'PRIVATE',supported_os:[] as string[],databases:'',protocols:'',scene_id:null as number|null,tier:'STANDARD',target_description:'',coverage_scope:'',architecture_summary:'',capability_coverage:'',implementation_notes:'',status:'SUPPORTED'})
const blankCatalog={...catalogForm,supported_os:[] as string[]}

function apiError(detail:any){if(Array.isArray(detail))return detail.map((item:any)=>item?.msg||item?.message||'字段校验失败').join('；');if(typeof detail==='string')return detail;return detail?.message||'请求失败'}
async function api(url:string,options:any={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...(options.headers||{})}});const data=response.status===204?null:await response.json();if(!response.ok)throw Error(apiError(data?.detail));return data}
async function signIn(){loginError.value='';try{const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify(loginForm)});token.value=data.access_token;localStorage.hzToken=token.value;user.value=data.user;await router.replace('/products')}catch(error:any){loginError.value=error.message}}
function logout(){localStorage.removeItem('hzToken');token.value='';user.value=null;rows.value=[];active.value=null}
async function loadCategories(){if(!categories.value.length)categories.value=await api('/api/product-categories')}
const phase2Routes=['home','ai-config','projects','project-detail','bom-rules','excel-templates','documents']
const routeAllowed=computed(()=>{const name=String(route.name);if(name==='system-admin')return can('USER_MANAGE');if(name==='ai-config')return can('BOM_EDIT');if(['projects','project-detail'].includes(name))return can('BOM_VIEW');if(['bom-rules','excel-templates'].includes(name))return can('KNOWLEDGE_MANAGE');if(name==='documents')return can('DOCUMENT_VIEW');return can('KNOWLEDGE_VIEW')})
async function loadRoute(){if(!user.value)return;if(phase2Routes.includes(String(route.name))){if(route.name==='home'){metrics.value=(await api('/api/dashboard')).metrics;rows.value=await api('/api/products')}active.value=null;return}loading.value=true;loadError.value='';try{if(route.name==='system-admin'){active.value=null;return}if(isDetail.value){const id=Number(route.params.id);if(currentCenter.value==='products')await loadCategories();active.value=await api('/api/'+currentCenter.value+'/'+id);return}active.value=null;rows.value=await api('/api/'+currentCenter.value)}catch(error:any){loadError.value=error.message||'知识数据加载失败'}finally{loading.value=false}}
async function navigate(key:string){await router.push(key==='home'?'/':'/'+key)}
async function openRecord(row:any){await router.push('/'+currentCenter.value+'/'+row.id)}
async function openRelation(relation:any){await router.push('/'+relation.type+'/'+relation.id)}

async function openCreate(){editingId.value=null;if(currentCenter.value==='products'){await loadCategories();Object.assign(productForm,{name:'',product_type:'HARDWARE',model_code:'',category_id:categories.value[0]?.id||null,summary:'',status:'ON_SALE',main_image:''});productDialog.value=true;return}dialogCenter.value=currentCenter.value;Object.assign(catalogForm,blankCatalog,{supported_os:[]});if(dialogCenter.value==='solutions'){sceneOptions.value=await api('/api/scenes');catalogForm.scene_id=sceneOptions.value[0]?.id||null}catalogDialog.value=true}
async function openEdit(row:any=active.value){if(!row?.id)return;await router.push({path:'/'+currentCenter.value+'/'+row.id,query:{edit:'1'}})}
const pairsToText=(value:Record<string,any>={})=>Object.entries(value||{}).map(([key,item])=>key+'='+item).join('\n')
const metricsToText=(value:any[]=[])=>(value||[]).map(item=>[item.name,item.value,item.unit,item.condition,item.source,item.dataset||'',item.sampleCount||'',item.inputResolution||'',item.hardware||'',item.runtime||''].join('|')).join('\n')
const definitionsToText=(value:any[]=[])=>(value||[]).map(item=>[item.name,item.dataType,item.description||''].join('|')).join('\n')
const textToPairs=(value:string)=>Object.fromEntries(value.split('\n').map(line=>line.split('=')).filter(parts=>parts[0]?.trim()).map(parts=>[parts[0].trim(),(parts[1]||'').trim()]))
const lines=(value:string)=>value.split('\n').map(item=>item.trim()).filter(Boolean)
async function saveProduct(){if(!productForm.name.trim()||!productForm.model_code.trim()||!productForm.category_id)return ElMessage.warning('请完整填写产品名称、主型号和分类');saving.value=true;try{const url='/api/products'+(editingId.value?'/'+editingId.value:'');const created=await api(url,{method:editingId.value?'PATCH':'POST',body:JSON.stringify(productForm)});productDialog.value=false;if(editingId.value)await loadRoute();else await router.push({path:'/products/'+created.id,query:{edit:'1'}});ElMessage.success(editingId.value?'产品已保存':'产品已创建，请继续完善详情')}catch(error:any){ElMessage.error(error.message||'产品保存失败')}finally{saving.value=false}}
async function saveProductDetails(value:any){try{await api('/api/products/'+active.value.id,{method:'PATCH',body:JSON.stringify(value)});active.value=await api('/api/products/'+active.value.id);await router.replace(route.path);ElMessage.success('产品详情已保存，刷新校验通过')}catch(error:any){ElMessage.error(error.message||'产品详情保存失败');throw error}}
async function moveProduct(row:any,direction:number){const index=rows.value.findIndex(item=>item.id===row.id),target=index+direction;if(index<0||target<0||target>=rows.value.length)return;const next=[...rows.value];[next[index],next[target]]=[next[target],next[index]];await api('/api/products/order',{method:'PATCH',body:JSON.stringify({items:next.map((item,display_order)=>({id:item.id,display_order}))})});rows.value=await api('/api/products');ElMessage.success('产品展示顺序已保存')}
async function saveProductMainImage(asset:any){
  try{
    await api('/api/products/'+active.value.id,{method:'PATCH',body:JSON.stringify({main_image:asset.url})})
    active.value=await api('/api/products/'+active.value.id)
    ElMessage.success('产品主图已保存并生效')
  }catch(error:any){
    await api('/api/media/images/'+String(asset.url||'').split('/').pop(),{method:'DELETE'}).catch(()=>null)
    active.value=await api('/api/products/'+active.value.id).catch(()=>active.value)
    ElMessage.error(error.message||'主图保存失败')
  }
}
async function saveKnowledgeDetails(value:any){saving.value=true;try{const endpoint=currentCenter.value==='products'?'/api/products/'+active.value.id:'/api/'+currentCenter.value+'/'+active.value.id;await api(endpoint,{method:'PATCH',body:JSON.stringify(value.record)});if(['software','algorithms'].includes(currentCenter.value)&&value.commercial)await api('/api/'+currentCenter.value+'/'+active.value.id+'/commercial',{method:'PATCH',body:JSON.stringify(value.commercial)});if(currentCenter.value==='solutions'&&value.bom)await api('/api/solutions/'+active.value.id+'/bom',{method:'PATCH',body:JSON.stringify(value.bom)});active.value=await api('/api/'+currentCenter.value+'/'+active.value.id);await router.replace(route.path);ElMessage.success('知识详情已保存')}finally{saving.value=false}}
async function saveProductPrice(value:any){await api('/api/products/'+active.value.id+'/prices',{method:'PATCH',body:JSON.stringify(value)});active.value=await api('/api/products/'+active.value.id);ElMessage.success('产品价格已保存')}
function structuredRows(value:string,model=false){return lines(value).map((line,index)=>{const [name,valueText='',unit='',condition='',source='',dataset='',sampleCount='',inputResolution='',hardware='',runtime='']=line.split('|');return {name,value:valueText,unit,condition,source,...(model?{dataset,sampleCount,inputResolution,hardware,runtime}:{}),sortOrder:index}})}
async function saveCatalog(){if(!catalogForm.name.trim())return ElMessage.warning('请输入名称');saving.value=true;try{let body:any={};const base={name:catalogForm.name,code:catalogForm.code,version:catalogForm.version,category:catalogForm.category,status:catalogForm.status,summary:catalogForm.summary};if(dialogCenter.value==='software')body={...base,description:catalogForm.description,logo:catalogForm.logo,softwareType:catalogForm.software_type,vendor:catalogForm.vendor,deploymentMode:catalogForm.deployment_mode,supportedOs:catalogForm.supported_os,databases:lines(catalogForm.databases),protocols:lines(catalogForm.protocols),boundaries:lines(catalogForm.boundaries),modules:lines(catalogForm.modules).map((line,index)=>{const[name,description='',featureText='']=line.split('|');return{name,description,sortOrder:index,features:featureText.split(';').filter(Boolean).map((feature,featureIndex)=>{const[featureName,featureDescription='']=feature.split(':');return{name:featureName,description:featureDescription,sortOrder:featureIndex}})}}),versions:lines(catalogForm.versions).map((line)=>{const[version,releasedAt='',summary='']=line.split('|');return{version,releasedAt:releasedAt||null,summary}}),screenshots:lines(catalogForm.screenshots).map((line,index)=>{const[image,title='']=line.split('|');return{image,title,sortOrder:index}})};if(dialogCenter.value==='algorithms')body={...base,principle:catalogForm.principle,inputSummary:catalogForm.input_summary,outputSummary:catalogForm.output_summary,parameters:structuredRows(catalogForm.parameters),metrics:structuredRows(catalogForm.metrics),boundaries:lines(catalogForm.boundaries)};if(dialogCenter.value==='model-capabilities')body={...base,modelType:catalogForm.model_type,taskType:catalogForm.task_type,functionType:catalogForm.function_type,metrics:structuredRows(catalogForm.metrics,true),inputDefinitions:lines(catalogForm.input_requirements).map((line,index)=>{const [name,dataType='JSON',description='',example='']=line.split('|');return {name,dataType,required:true,description,example,sortOrder:index}}),outputDefinitions:lines(catalogForm.output_definitions).map((line,index)=>{const [name,dataType='JSON',description='',example='']=line.split('|');return {name,dataType,description,example,sortOrder:index}}),deploymentRequirements:textToPairs(catalogForm.deployment_requirements),useConditions:lines(catalogForm.use_conditions),boundaries:lines(catalogForm.boundaries)};if(dialogCenter.value==='scenes')body={name:catalogForm.name,category:catalogForm.category,summary:catalogForm.summary,coverImage:catalogForm.cover_image,status:catalogForm.status,tags:lines(catalogForm.tags),conditions:lines(catalogForm.conditions),painPoints:lines(catalogForm.pain_points).map((line,index)=>{const[title,description='']=line.split('|');return{title,description,sortOrder:index}}),goals:lines(catalogForm.goals).map((line,index)=>{const[title,description='']=line.split('|');return{title,description,sortOrder:index}}),process:lines(catalogForm.business_process).map((line,index)=>{const[nodeTitle,nodeDescription='']=line.split('|');return{nodeTitle,nodeDescription,sortOrder:index}}),coreCapabilitySummary:catalogForm.core_capability_summary};if(dialogCenter.value==='solutions')body={...base,sceneId:catalogForm.scene_id,tier:catalogForm.tier,targetDescription:catalogForm.target_description,coverageScope:catalogForm.coverage_scope,implementationNotes:catalogForm.implementation_notes,architecture:lines(catalogForm.architecture_summary).map((line,index)=>{const [layer,name,description='',relationType='',relationId='']=line.split('|');return {layer,name,description,relationType,relationId:relationId?Number(relationId):null,sortOrder:index}}),capabilityCoverage:lines(catalogForm.capability_coverage).map((line,index)=>{const [capabilityName,status='COVERED',implementation='',notes='']=line.split('|');return {capabilityName,status,implementation,notes,sortOrder:index}})};const url=(dialogCenter.value==='products'?'/api/products':'/api/'+dialogCenter.value)+(editingId.value?'/'+editingId.value:'');await api(url,{method:editingId.value?'PATCH':'POST',body:JSON.stringify(body)});catalogDialog.value=false;await loadRoute();ElMessage.success('知识条目已保存')}catch(error:any){ElMessage.error(error?.message||'知识条目保存失败')}finally{saving.value=false}}
async function deleteRecord(row:any=active.value){await ElMessageBox.confirm('删除后不可恢复，确认继续？','删除知识条目',{type:'warning'});await api(currentCenter.value==='products'?'/api/products/'+row.id:'/api/'+currentCenter.value+'/'+row.id,{method:'DELETE'});ElMessage.success('知识条目已删除');await router.push('/'+currentCenter.value)}

async function loadRelationOptions(kind:string){return api('/api/'+kind)}
async function addRelation(payload:any){await api('/api/relations',{method:'POST',body:JSON.stringify(payload)});active.value=await api('/api/'+currentCenter.value+'/'+active.value.id);relationDrawer.value=false;ElMessage.success('关联已建立')}
async function editRelation(relationId:number,payload:any){await api('/api/relations/'+relationId,{method:'PATCH',body:JSON.stringify(payload)});active.value=await api('/api/'+currentCenter.value+'/'+active.value.id);relationDrawer.value=false;ElMessage.success('关系已更新')}
async function removeRelation(relation:any){await ElMessageBox.confirm('确认移除该知识关联？','移除关联',{type:'warning'});await api('/api/relations/'+relation.relationId,{method:'DELETE'});active.value=await api('/api/'+currentCenter.value+'/'+active.value.id);ElMessage.success('关联已移除')}
async function openBom(){rows.value=await api('/api/products');bomRows.value=(active.value.bom?.items||[]).map((item:any)=>({product_id:item.productId,quantity:item.quantity,unit:item.unit,purpose:item.purpose,requirement_level:item.requirementLevel,recommendation_reason:item.recommendationReason}));bomDialog.value=true}
function addBom(){bomRows.value.push({product_id:rows.value[0]?.id||null,quantity:1,unit:'台',purpose:'',requirement_level:'REQUIRED',recommendation_reason:''})}
async function saveBom(){saving.value=true;try{await api('/api/solutions/'+active.value.id+'/bom',{method:'PATCH',body:JSON.stringify({items:bomRows.value})});active.value=await api('/api/solutions/'+active.value.id);bomDialog.value=false;ElMessage.success('标准BOM已保存')}finally{saving.value=false}}

watch(()=>route.fullPath,loadRoute)
onMounted(async()=>{if(token.value){try{user.value=await api('/api/auth/me');if(!can('KNOWLEDGE_VIEW'))throw Error('当前账号没有知识查看权限');await loadRoute()}catch{logout()}}})
</script>

<template>
 <main v-if="!token" class="login"><section class="login-card"><div class="brand"><div class="brand-mark">海</div><b>海智产品中心</b></div><h1>六大知识中心</h1><p>产品、软件、算法、模型能力、场景与方案的一体化知识平台</p><el-alert v-if="loginError" :title="loginError" type="error" :closable="false" show-icon/><el-form label-position="top" @submit.prevent="signIn"><el-form-item label="账号"><el-input v-model="loginForm.username" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="loginForm.password" type="password" show-password autocomplete="current-password"/></el-form-item><el-button type="primary" native-type="submit" @click="signIn">登录</el-button></el-form></section></main>
 <main v-else class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">海</div><b>海智产品中心</b></div><div class="nav-title">业务工作台</div><el-menu :default-active="String(route.name)" @select="(key:string)=>router.push(key==='home'?'/':'/'+key)"><el-menu-item index="home"><el-icon><House/></el-icon><span>首页</span></el-menu-item><el-menu-item v-if="can('BOM_EDIT')" index="ai-config"><el-icon><ChatDotRound/></el-icon><span>智能配单</span></el-menu-item><el-menu-item v-if="can('BOM_VIEW')" index="projects"><el-icon><List/></el-icon><span>项目配单</span></el-menu-item><el-menu-item v-if="can('DOCUMENT_VIEW')" index="documents"><el-icon><Document/></el-icon><span>资料中心</span></el-menu-item><div class="nav-title">知识中心</div><el-menu-item v-for="center in centers" :key="center.key" :index="center.key"><el-icon><component :is="center.icon"/></el-icon><span>{{center.label}}</span></el-menu-item><div v-if="can('KNOWLEDGE_MANAGE')" class="nav-title">业务配置</div><el-menu-item v-if="can('KNOWLEDGE_MANAGE')" index="bom-rules"><el-icon><Setting/></el-icon><span>BOM规则</span></el-menu-item><el-menu-item v-if="can('KNOWLEDGE_MANAGE')" index="excel-templates"><el-icon><Tickets/></el-icon><span>Excel模板</span></el-menu-item><el-menu-item v-if="can('USER_MANAGE')" index="system-admin"><el-icon><Setting/></el-icon><span>系统管理</span></el-menu-item></el-menu></aside>
  <section class="workspace"><header class="header"><div><b>{{route.name==='system-admin'?'系统管理':isDetail?'知识详情':currentMeta.label}}</b><span>{{route.name==='system-admin'?'用户、角色与权限':'六大知识中心'}}</span></div><div class="user"><el-avatar>{{user?.displayName.slice(0,1)}}</el-avatar><span><b>{{user?.displayName}}</b><small>{{can('USER_MANAGE')?'系统管理员':can('KNOWLEDGE_MANAGE')?'产品经理':can('BOM_EDIT')?'销售人员':'只读用户'}}</small></span><el-button text @click="logout">退出</el-button></div></header><div class="content">
   <el-result v-if="!routeAllowed" icon="warning" title="无权访问此页面" sub-title="请联系系统管理员分配相应业务权限"><template #extra><el-button type="primary" @click="router.push('/')">返回首页</el-button></template></el-result>
   <Phase2Workspace v-else-if="phase2Routes.includes(String(route.name))" :token="token" :permissions="user?.permissions||[]"/>
   <SystemAdmin v-else-if="route.name==='system-admin'" :token="token"/>
   <ProductList v-else-if="!isDetail&&currentCenter==='products'" :rows="rows" :loading="loading" :error="loadError" :can-manage="can('KNOWLEDGE_MANAGE')" :show-price="can('PRICE_VIEW')" @create="openCreate" @open="openRecord" @edit="openEdit" @delete="deleteRecord" @move="moveProduct" @retry="loadRoute"/>
   <KnowledgeList v-else-if="!isDetail" :title="currentMeta.label" :center-key="currentCenter" :description="currentMeta.description" :search-placeholder="currentMeta.placeholder" :rows="rows" :loading="loading" :error="loadError" :can-manage="can('KNOWLEDGE_MANAGE')" @create="openCreate" @open="openRecord" @edit="openEdit" @delete="deleteRecord" @retry="loadRoute"/>
   <ProductDetail v-else-if="currentCenter==='products'&&active" :record="active" :categories="categories" :can-manage="can('KNOWLEDGE_MANAGE')" :can-download="can('DOCUMENT_DOWNLOAD')" :show-price="can('PRICE_VIEW')" :start-editing="route.query.edit==='1'" @back="router.push('/products')" @save="saveProductDetails" @save-main-image="saveProductMainImage" @save-price="saveProductPrice" @delete="deleteRecord" @relate="relationDrawer=true" @open-relation="openRelation"/>
   <KnowledgeDetail v-else :center-title="currentMeta.label" :center-key="currentCenter" :record="active" :loading="loading" :error="loadError" :can-manage="can('KNOWLEDGE_MANAGE')" :can-download="can('DOCUMENT_DOWNLOAD')" :show-price="can('PRICE_VIEW')" :start-editing="route.query.edit==='1'" @back="router.push('/'+currentCenter)" @edit="openEdit" @save="saveKnowledgeDetails" @delete="deleteRecord" @relate="relationDrawer=true" @edit-bom="openEdit" @retry="loadRoute" @open-relation="openRelation"/>
  </div></section>
 </main>

 <RelationDrawer v-if="active" v-model="relationDrawer" :source-type="currentCenter" :source-id="active.id" :relations="active.relations||[]" :load-options="loadRelationOptions" @add="addRelation" @edit="editRelation" @remove="removeRelation"/>
 <el-dialog v-model="productDialog" title="新增产品" width="600px"><el-form label-position="top"><div class="dialog-grid"><el-form-item label="产品名称" required><el-input v-model="productForm.name"/></el-form-item><el-form-item label="产品类型" required><el-select v-model="productForm.product_type"><el-option label="硬件产品" value="HARDWARE"/><el-option label="软件产品" value="SOFTWARE_PRODUCT"/><el-option label="系统产品" value="SYSTEM_PRODUCT"/><el-option label="配套设备" value="ACCESSORY"/></el-select></el-form-item><el-form-item label="主型号" required><el-input v-model="productForm.model_code"/></el-form-item><el-form-item label="分类" required><el-select v-model="productForm.category_id"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="销售状态"><el-select v-model="productForm.status"><el-option label="在售" value="ON_SALE"/><el-option label="停售" value="OFF_SALE"/></el-select></el-form-item><el-form-item label="一句话简介" class="dialog-span"><el-input v-model="productForm.summary" type="textarea" :rows="3"/></el-form-item></div><ImageUpload v-model="productForm.main_image" label="产品主图"/></el-form><template #footer><el-button @click="productDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveProduct">创建并完善详情</el-button></template></el-dialog>

<el-dialog v-model="catalogDialog" :title="(editingId?'编辑':'新增') + centers.find(item=>item.key===dialogCenter)?.label" width="760px" class="knowledge-editor">
  <el-form label-position="top"><div class="dialog-grid">
    <el-form-item label="名称" required><el-input v-model="catalogForm.name"/></el-form-item>
    <el-form-item v-if="['software','algorithms','model-capabilities','solutions'].includes(dialogCenter)" label="编码"><el-input v-model="catalogForm.code"/></el-form-item>
    <el-form-item v-if="['software','algorithms','model-capabilities'].includes(dialogCenter)" label="当前版本"><el-input v-model="catalogForm.version"/></el-form-item>
    <el-form-item v-if="['algorithms','model-capabilities','scenes','solutions'].includes(dialogCenter)" label="分类"><el-input v-model="catalogForm.category"/></el-form-item>

    <template v-if="dialogCenter==='software'">
      <el-form-item label="软件类型"><el-select v-model="catalogForm.software_type"><el-option label="平台软件" value="PLATFORM"/><el-option label="客户端软件" value="CLIENT"/><el-option label="服务组件" value="SERVICE"/></el-select></el-form-item>
      <el-form-item label="厂商"><el-input v-model="catalogForm.vendor"/></el-form-item>
      <el-form-item label="部署方式"><el-select v-model="catalogForm.deployment_mode"><el-option label="私有化部署" value="PRIVATE"/><el-option label="云端部署" value="CLOUD"/><el-option label="混合部署" value="HYBRID"/></el-select></el-form-item>
      <el-form-item label="支持操作系统"><el-select v-model="catalogForm.supported_os" multiple allow-create filterable><el-option label="Linux" value="Linux"/><el-option label="Windows" value="Windows"/><el-option label="国产操作系统" value="国产操作系统"/></el-select></el-form-item>
      <el-form-item label="Logo地址" class="dialog-span"><el-input v-model="catalogForm.logo"/></el-form-item>
      <el-form-item label="数据库"><el-input v-model="catalogForm.databases" type="textarea" placeholder="每行一种数据库"/></el-form-item>
      <el-form-item label="支持协议"><el-input v-model="catalogForm.protocols" type="textarea" placeholder="每行一种协议"/></el-form-item>
      <el-form-item label="功能模块" class="dialog-span"><el-input v-model="catalogForm.modules" type="textarea" :rows="4" placeholder="每行：模块名称|模块说明|功能名:功能说明;功能名:功能说明"/></el-form-item>
      <el-form-item label="版本记录" class="dialog-span"><el-input v-model="catalogForm.versions" type="textarea" placeholder="每行：版本|发布日期|更新摘要"/></el-form-item>
      <el-form-item label="软件截图" class="dialog-span"><el-input v-model="catalogForm.screenshots" type="textarea" placeholder="每行：图片地址|图片标题"/></el-form-item>
      <el-form-item label="详细介绍" class="dialog-span"><el-input v-model="catalogForm.description" type="textarea" :rows="3"/></el-form-item>
      <el-form-item label="能力边界" class="dialog-span"><el-input v-model="catalogForm.boundaries" type="textarea" placeholder="每行一项"/></el-form-item>
    </template>

    <template v-if="dialogCenter==='algorithms'">
      <el-form-item label="算法原理" class="dialog-span"><el-input v-model="catalogForm.principle" type="textarea" :rows="3"/></el-form-item>
      <el-form-item label="输入数据" class="dialog-span"><el-input v-model="catalogForm.input_summary" type="textarea"/></el-form-item>
      <el-form-item label="输出数据" class="dialog-span"><el-input v-model="catalogForm.output_summary" type="textarea"/></el-form-item>
      <el-form-item label="核心参数" class="dialog-span"><el-input v-model="catalogForm.parameters" type="textarea" placeholder="每行：名称|值|单位|条件|来源"/></el-form-item>
    </template>

    <template v-if="['algorithms','model-capabilities'].includes(dialogCenter)">
      <el-form-item v-if="dialogCenter==='model-capabilities'" label="模型类型"><el-select v-model="catalogForm.model_type"><el-option label="目标检测" value="DETECTION"/><el-option label="文字识别" value="OCR"/><el-option label="分类" value="CLASSIFICATION"/><el-option label="分割" value="SEGMENTATION"/><el-option label="跟踪" value="TRACKING"/><el-option label="时序分析" value="TIME_SERIES"/><el-option label="多模态" value="MULTIMODAL"/></el-select></el-form-item>
      <el-form-item v-if="dialogCenter==='model-capabilities'" label="任务类型"><el-input v-model="catalogForm.task_type"/></el-form-item>
      <el-form-item v-if="dialogCenter==='model-capabilities'" label="功能类型"><el-select v-model="catalogForm.function_type"><el-option v-for="item in ['识别','检测','跟踪','融合','预测','分析']" :key="item" :label="item" :value="item"/></el-select></el-form-item>
      <el-form-item label="性能指标" class="dialog-span"><el-input v-model="catalogForm.metrics" type="textarea" placeholder="每行：名称|值|单位|条件|来源；模型可继续填写数据集、样本数、分辨率、硬件、运行时"/></el-form-item>
      <el-form-item v-if="dialogCenter==='model-capabilities'" label="输入定义" class="dialog-span"><el-input v-model="catalogForm.input_requirements" type="textarea" placeholder="每行：名称|数据类型|说明|示例"/></el-form-item>
      <el-form-item v-if="dialogCenter==='model-capabilities'" label="输出定义" class="dialog-span"><el-input v-model="catalogForm.output_definitions" type="textarea" placeholder="每行：名称|数据类型|说明|示例"/></el-form-item>
      <el-form-item v-if="dialogCenter==='model-capabilities'" label="部署要求" class="dialog-span"><el-input v-model="catalogForm.deployment_requirements" type="textarea" placeholder="每行：名称=值"/></el-form-item>
      <el-form-item v-if="dialogCenter==='model-capabilities'" label="使用条件" class="dialog-span"><el-input v-model="catalogForm.use_conditions" type="textarea" placeholder="每行一项"/></el-form-item>
      <el-form-item label="能力边界" class="dialog-span"><el-input v-model="catalogForm.boundaries" type="textarea" placeholder="每行一项"/></el-form-item>
    </template>

    <template v-if="dialogCenter==='scenes'">
      <el-form-item label="封面图"><el-input v-model="catalogForm.cover_image"/></el-form-item>
      <el-form-item label="场景标签"><el-input v-model="catalogForm.tags" type="textarea" placeholder="每行一个标签"/></el-form-item>
      <el-form-item label="关键条件" class="dialog-span"><el-input v-model="catalogForm.conditions" type="textarea" placeholder="每行一项"/></el-form-item>
      <el-form-item label="业务痛点" class="dialog-span"><el-input v-model="catalogForm.pain_points" type="textarea" placeholder="每行：标题|说明"/></el-form-item>
      <el-form-item label="建设目标" class="dialog-span"><el-input v-model="catalogForm.goals" type="textarea" placeholder="每行：标题|说明"/></el-form-item>
      <el-form-item label="业务流程" class="dialog-span"><el-input v-model="catalogForm.business_process" type="textarea" placeholder="每行：节点名称|节点说明"/></el-form-item>
      <el-form-item label="核心模型能力" class="dialog-span"><el-input v-model="catalogForm.core_capability_summary" type="textarea"/></el-form-item>
    </template>

    <template v-if="dialogCenter==='solutions'">
      <el-form-item label="关联场景"><el-select v-model="catalogForm.scene_id"><el-option v-for="item in sceneOptions" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item>
      <el-form-item label="方案等级"><el-select v-model="catalogForm.tier"><el-option label="标准方案" value="STANDARD"/><el-option label="增强方案" value="ENHANCED"/><el-option label="旗舰方案" value="FLAGSHIP"/></el-select></el-form-item>
      <el-form-item label="方案目标" class="dialog-span"><el-input v-model="catalogForm.target_description" type="textarea"/></el-form-item>
      <el-form-item label="覆盖范围" class="dialog-span"><el-input v-model="catalogForm.coverage_scope" type="textarea"/></el-form-item>
      <el-form-item label="方案架构" class="dialog-span"><el-input v-model="catalogForm.architecture_summary" type="textarea" :rows="4" placeholder="每行：层级|节点名称|说明|关联中心|关联ID"/></el-form-item>
      <el-form-item label="能力覆盖" class="dialog-span"><el-input v-model="catalogForm.capability_coverage" type="textarea" placeholder="每行：能力名称|COVERED/OPTIONAL/NOT_COVERED|实现方式|备注"/></el-form-item>
      <el-form-item label="实施说明" class="dialog-span"><el-input v-model="catalogForm.implementation_notes" type="textarea"/></el-form-item>
    </template>

    <el-form-item label="状态"><el-select v-model="catalogForm.status"><el-option label="正式支持" value="SUPPORTED"/><el-option label="已发布" value="PUBLISHED"/><el-option label="启用" value="ACTIVE"/><el-option label="Beta" value="BETA"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item>
    <el-form-item label="一句话简介" class="dialog-span"><el-input v-model="catalogForm.summary" type="textarea" :rows="3"/></el-form-item>
  </div></el-form>
  <template #footer><el-button @click="catalogDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCatalog">保存</el-button></template>
 </el-dialog>

 <el-dialog v-model="bomDialog" title="编辑标准BOM" width="920px"><div class="bom-editor-actions"><span>引用产品中心中的真实产品与主型号。</span><el-button :icon="Plus" @click="addBom">添加产品</el-button></div><el-table :data="bomRows" border><el-table-column label="产品" min-width="190"><template #default="scope"><el-select v-model="scope.row.product_id" filterable><el-option v-for="item in rows" :key="item.id" :label="item.name+' · '+item.modelCode" :value="item.id"/></el-select></template></el-table-column><el-table-column label="数量" width="110"><template #default="scope"><el-input-number v-model="scope.row.quantity" :min="1"/></template></el-table-column><el-table-column label="单位" width="80"><template #default="scope"><el-input v-model="scope.row.unit"/></template></el-table-column><el-table-column label="用途" min-width="130"><template #default="scope"><el-input v-model="scope.row.purpose"/></template></el-table-column><el-table-column label="要求" width="110"><template #default="scope"><el-select v-model="scope.row.requirement_level"><el-option label="必选" value="REQUIRED"/><el-option label="推荐" value="RECOMMENDED"/><el-option label="可选" value="OPTIONAL"/></el-select></template></el-table-column><el-table-column label="推荐理由" min-width="150"><template #default="scope"><el-input v-model="scope.row.recommendation_reason"/></template></el-table-column><el-table-column width="54"><template #default="scope"><el-button link type="danger" @click="bomRows.splice(scope.$index,1)">删除</el-button></template></el-table-column></el-table><template #footer><el-button @click="bomDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveBom">保存BOM</el-button></template></el-dialog>
</template>
